import {mountCustomerClarity,customerProgressMarkup} from './customer-clarity.mjs';
import {esc,when,conversation,request} from './customer-shared.mjs';
import {mountCustomerSelfCheck} from './customer-self-check.mjs';
import {mountCustomerPromise,promiseMarkup} from './access-assurance-ui.mjs';
import {passportMarkup} from './recovery-passport-ui.mjs';
const root=document.querySelector('#customer-app');let current=null,pendingId=null,pendingText=null,busy=false;
function landing(note=''){root.innerHTML=`<div class="customer-landing"><div class="customer-hero"><span class="customer-eyebrow">PURCHASE SUPPORT</span><h1>Paid for it.<br>Still waiting for access?</h1><p>Find your recovery request, follow each update, and talk to the merchant in one place.</p></div><section class="customer-card" style="margin-top:24px"><h2>Find your purchase</h2><p>If email delivery is configured, we’ll send a private link to the purchase email registered by your merchant. Your order details stay private.</p><form id="find"><label for="reference">Order or case reference</label><small id="reference-hint">Find this on your purchase receipt or in a message from the merchant. Example case: CL-1234.</small><input id="reference" name="reference" required maxlength="150" autocomplete="off" aria-describedby="reference-hint" placeholder="Order ID or CL-…"><label for="email">Purchase email</label><input id="email" name="email" type="email" required maxlength="254" autocomplete="email"><button class="primary">Request a private case link</button></form><p id="lookup-status" role="status">${esc(note)}</p><small>If no case has been registered, ask your merchant to register the purchase first. If email is unavailable, ask the merchant to share a private case link. This demo does not search external store orders.</small><div class="customer-demo-entry"><span>Exploring PayTrace?</span><a href="demo.html">See the sample recovery</a><small>The sample story does not access your private case.</small></div></section></div>`;root.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const d=await request('/api/customer/request-link',{reference:e.target.reference.value,email:e.target.email.value});root.querySelector('#lookup-status').textContent=d.message;}catch(err){root.querySelector('#lookup-status').textContent=err.message;}finally{b.disabled=false;}};}
async function openLesson(event){
 const button=event.currentTarget,caseId=current.caseId;button.disabled=true;
 try{
  const lesson=await request('/api/customer/lesson?caseId='+encodeURIComponent(caseId)),box=root.querySelector('#lesson-result');
  box.textContent=lesson.title+' '+lesson.body;box.className='customer-lesson';
  if(!lesson.browserChallenge||!crypto.subtle){box.insertAdjacentHTML('beforeend','<p class="buyer-proof-note">The lesson opened. This browser cannot record the separate receipt.</p>');return;}
  try{
   const bytes=new TextEncoder().encode(lesson.body),digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(x=>x.toString(16).padStart(2,'0')).join('');
   const proof=await request('/api/customer/browser-proof',{caseId,token:lesson.browserChallenge,digest});
   box.insertAdjacentHTML('beforeend',`<p class="buyer-proof-note">${esc(proof.detail)}</p>`);
   if(current.caseId===caseId&&current.accessPromise){current.accessPromise={...current.accessPromise,browserProofAt:proof.at,state:current.sample?'sample':current.confirmedAt&&!current.help?'customer-confirmed':'buyer-browser-reached',explanation:current.sample?current.accessPromise.explanation:current.confirmedAt&&!current.help?'The technical check passed and you separately confirmed access.':'Protected lesson content reached this private browser session. Your confirmation is separate.'};const card=root.querySelector('.access-promise');if(card)card.outerHTML=promiseMarkup(current.accessPromise,{customer:true});}
  }catch{box.insertAdjacentHTML('beforeend','<p class="buyer-proof-note">The lesson opened, but its browser receipt was not recorded. You can try again or tell the merchant what happened.</p>');}
 }catch(error){root.querySelector('#feedback').textContent=error.message;}
 finally{button.disabled=false;}
}
function render(s){current=s;const title=s.paymentHold?'We’re reviewing a payment change.':s.help?'We’re keeping your request open.':s.request?'A little information will help.':s.confirmedAt&&s.verified?'You’re back in.':s.verified?'Your purchase is ready to open.':s.status===2?'One more check before you’re back in.':'Let’s get you back to your purchase.';
 root.innerHTML=`<section class="customer-hero"><span class="customer-eyebrow">YOUR PURCHASE / ${esc(s.customerName)}</span><h1>${title}</h1><p>${esc(s.next)}. Your payment and access are checked separately. You don’t need to purchase the item again.</p><span class="status-chip">${s.sample?'Demonstration · sample purchase':'PayPal sandbox purchase'}</span>${customerProgressMarkup(s)}</section>${passportMarkup(s.passport,{customer:true})}<div class="customer-layout ${s.verified?'resolved':''}"><section class="customer-card" id="customer-conversation"><span class="customer-eyebrow">YOUR CONVERSATION</span><h2>Your updates. One conversation.</h2><p>Ask a question or tell the merchant what happens when you try to open your purchase.</p>${s.request?`<div class="customer-alert"><strong>Your reply is needed</strong><br>${esc(s.request)}<br><small>Reply below. Never share your password or full card details.</small></div>`:''}<div class="customer-thread" aria-label="Case messages">${conversation(s.messages)}</div><form id="reply"><label for="message">Message the merchant</label><textarea id="message" name="message" maxlength="2000" required placeholder="Tell us what you see, or ask a question…">${esc(pendingText||'')}</textarea><small>Up to 2,000 characters. Replies appear here. You can check for updates at any time; response times depend on your merchant.</small><div class="customer-actions"><button class="primary">Send message</button><button type="button" id="refresh">Refresh updates</button></div></form><p id="feedback" class="customer-error" role="status"></p><p class="customer-live">Last checked ${esc(when(new Date().toISOString()))} · refresh for new updates</p></section><aside><section class="customer-card"><span class="customer-eyebrow">WHAT YOU PURCHASED</span><div class="customer-meta"><div class="purchase-icon" aria-hidden="true"><svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 3h12a4 4 0 0 1 4 4v14H8a4 4 0 0 1-4-4z M4 16h16 M8 7h8 M8 11h5"/></svg></div><div><strong>${esc(s.course)}</strong><p style="margin:4px 0">${esc(s.amount)}</p></div></div><p class="customer-reference">Order ${esc(s.orderReference)}<br>Case ${esc(s.caseId)}</p><hr style="border:0;border-top:1px solid #e3ebf4"><p><strong>Who’s up next?</strong><br>${esc(s.next)}</p>${s.verified?`<button class="primary" id="lesson">Open my purchase</button><div id="lesson-result" role="status"></div><div class="customer-actions"><button id="confirm">${s.confirmedAt?'✓ You confirmed access':'It works — thank you'}</button></div>`:'<small>The access button appears after the technical check passes.</small>'}<div class="customer-actions"><button id="help">I still need help</button></div><p><small>Technical access check: ${s.verified?'passed':'not yet confirmed'}<br>Your confirmation: ${s.confirmedAt&&s.verified?'received':'not yet received'}</small></p></section><section class="customer-card"><h2>Where to find updates</h2><p>The latest recorded merchant reply and planned update time appear above. Use Refresh updates to check for changes, or send a question in the conversation.</p><small>Email alerts depend on merchant setup; this private page remains available even if no email arrives.</small></section></aside></div>`;
 mountCustomerClarity(root,s,{pending:!!pendingId});
 mountCustomerPromise(root,s);
 mountCustomerSelfCheck(root,s);
 root.querySelector('#reply').onsubmit=async e=>{e.preventDefault();if(busy)return;const text=e.target.message.value;if(!pendingId){pendingId=crypto.randomUUID();pendingText=text;}await action({action:'message',text:pendingText,requestId:pendingId},true);};
 root.querySelector('#refresh').onclick=()=>load();root.querySelector('#help').onclick=()=>action({action:'help',requestId:crypto.randomUUID()});root.querySelector('#confirm')?.addEventListener('click',()=>action({action:'confirm',requestId:crypto.randomUUID()}));
 root.querySelector('#lesson')?.addEventListener('click',openLesson);
}
async function action(body,clear=false){if(busy)return;busy=true;root.querySelectorAll('button').forEach(b=>b.disabled=true);try{const s=await request('/api/customer/message',{...body,caseId:current.caseId});if(clear){pendingId=null;pendingText=null;}render(s);}catch(e){if(e.rejected){pendingId=null;pendingText=null;}root.querySelector('#feedback').textContent=e.message+(pendingId?' Retry sends your original message once.':'');root.querySelector('#message').disabled=!!pendingId;}finally{busy=false;root.querySelectorAll('button').forEach(b=>b.disabled=false);}}
async function load(){if(busy)return;const draft=root.querySelector('#message')?.value;try{const s=await request('/api/customer/case'+(current?'?caseId='+encodeURIComponent(current.caseId):''));render(s);if(draft&&!pendingText){root.querySelector('#message').value=draft;root.querySelector('#message').dispatchEvent(new Event('input'));}}catch(e){if(current)root.querySelector('#feedback').textContent='Updates could not be refreshed. '+e.message;else landing(e.message);}}
async function openPrivateCase(){try{if(location.hash.length>1){current=null;pendingId=null;pendingText=null;const token=location.hash.slice(1);history.replaceState(null,'',location.pathname);await request('/api/customer/session',{token});}await load();}catch(e){landing(e.message);}}
window.addEventListener('hashchange',openPrivateCase);await openPrivateCase();
